 async function click(e){const b=e.target.closest('button');if(!b||!root.contains(b))return;if(b.dataset.mode&&!game){settings.mode=b.dataset.mode;render();return;}if(b.dataset.category&&!game){const c=b.dataset.category;settings.categories=settings.categories.includes(c)?settings.categories.filter(x=>x!==c):settings.categories.concat(c);render();return;}if(b.dataset.seat!==undefined&&!game){editSeat(+b.dataset.seat);return;}const a=b.dataset.act,now=performance.now();if(a==='save-seat'&&editingSeat!==null){const i=editingSeat%settings.teams.length,j=Math.floor(editingSeat/settings.teams.length);settings.teams[i].members[j]=modal.querySelector('[data-seat-name]').value.trim().slice(0,24);render();close();return;}if(a==='sound'){if(busy)return;busy=true;muted=!muted;const ok=await audio.enable(!muted);busy=false;if(disposed)return;if(!ok)muted=true;b.setAttribute('aria-pressed',String(!muted));b.setAttribute('aria-label',muted?'روشن کردن موسیقی و افکت':'قطع موسیقی و افکت');b.innerHTML=icon(muted?'volume-x':'volume-2');icons();syncSound();return;}if(a==='help'||a==='reset'){dialog(a);return;}if(a==='close'){close();return;}if(a==='settings'){close();game=null;step=1;audio.music(false);render();return;}if(a==='rules'){step=2;render();focus('start');return;}if(a==='teams'){step=1;render();return;}if(a==='start'){start();return;}if(!game)return;if(a==='continue-bomb'||a==='continue-timeout'){if(a==='continue-bomb'?game.continueAfterExplosion(now):game.continueAfterTimeout(now)){lastClick=now;lastBombPulse=-Infinity;render();syncSound();focus('correct');announce('نوبت '+game.player);}return;}if(a==='pause'){game.phase==='paused'?game.resume(now):game.pause(now);render();syncSound();return;}if(['correct','skip','foul'].includes(a)){if(now-lastClick<300)return;lastClick=now;const before=game.phase,beforeSeat=game.seat,beforeRound=game.round;if(game.act(a,now)){audio.effect(a==='correct'?'correct':'pass');render();syncSound();if(a==='skip')focus('skip');if(['handoff','playing'].includes(game.phase))announce(game.notice+' نوبت '+game.player);}else if(before!==game.phase||beforeSeat!==game.seat||beforeRound!==game.round){render();syncSound();}return;}}
 function key(e){if(modal.hidden)return;if(e.key==='Escape')close();if(e.key==='Enter'&&e.target.matches('[data-seat-name]')){e.preventDefault();modal.querySelector('[data-act=save-seat]').click();}if(e.key==='Tab'){const buttons=[...modal.querySelectorAll('input,button')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus();}}}
 const interval=setInterval(()=>{if(!game||!game.running)return;if(!visible()){pauseHidden();return;}const before=game.phase,beforeSeat=game.seat,beforeRound=game.round;game.tick(performance.now());if(game.phase!==before||game.seat!==beforeSeat||game.round!==beforeRound){if(game.timeouts===seenTimeouts&&game.phase!=='exploded'&&!(game.config.bombEnabled&&game.phase==='playing'))audio.effect(game.phase==='playing'?'tick':'end');render();syncSound();if(game.phase==='playing'){lastClick=performance.now();lastTick=-1;focus('correct');announce('نوبت '+game.player);}else announce(game.notice+' '+(game.phase==='finished'?'بازی تمام شد':'نوبت '+game.player));}else{clock();const sec=Math.ceil(game.clock/1000);if(!game.config.bombEnabled&&game.phase==='playing'&&sec<=5&&sec!==lastTick){lastTick=sec;audio.effect('tick');}}bombFeedback(performance.now());},50);
